<script setup lang="ts">import type {Result} from '../types/entities';import {percent,difference} from '../utils/format';import PathRibbon from './PathRibbon.vue';defineProps<{result:Result;limit?:number}>()</script><template><div class="table-scroll"><table><thead><tr><th>有序子序列</th><th>旅程支持度</th><th>转化 / 退出组</th><th>差值</th></tr></thead><tbody><tr v-for="p in result.patterns.slice(0,limit||200)" :key="p.pattern.join('>')"><td><PathRibbon :path="p.pattern" :dictionary="result.dictionary" compact/></td><td><b>{{percent(p.support)}}</b><small>{{p.count}} / {{result.journeys}} 条</small></td><td><div class="support-pair"><i :style="{width:((p.converted_support||0)*70)+'px'}"/><b>{{percent(p.converted_support)}}</b></div><div class="support-pair exited"><i :style="{width:((p.exited_support||0)*70)+'px'}"/><b>{{percent(p.exited_support)}}</b></div></td><td>{{difference(p.support_difference)}}</td></tr></tbody></table></div></template>
